CREATE PROCEDURE [dbo].[usp_AIMNutrient_SEL_IsActive]    @IsActive  BITASBEGINSET NOCOUNT ON;    -- Set T-WHERE string ----  SELECT     NN.*   -- 1/11/21 - changed to remove aspnet_User table (and use CFCUser instead)	   --, AU.UserName   , U.UserNameFROM    dbo.AIMNutrient NN WITH(NOLOCK)LEFT OUTER JOIN    CFCUser.CFCUser U WITH(NOLOCK)     ON NN.CFCUserID = U.CFCUserID-- 1/11/21 - changed to remove aspnet_User table (and use CFCUser instead)--LEFT OUTER JOIN--     dbo.aspnet_Users AU WITH(NOLOCK)--      ON AU.UserId = U.UserIDWHERE    NN.IsActive = @IsActiveEND
